import numpy as np,json
from PIL import Image
from rcb_client import Robot
S=json.load(open('/app/output/spec.json')); R=np.array(S['qpos']['range']); names=S['qpos']['layout']
def action(q): return np.clip(2*(np.array(q)-R[:,0])/(R[:,1]-R[:,0])-1,-1,1)
def readq(): return np.load('/app/output/target.npy')
def save(o):
 for k,v in o.get('images',{}).items(): Image.fromarray(v).save('/app/output/'+k+'.png')
 np.savez('/app/output/current.npz',q=o['proprio']['joint_pos'],v=o['proprio']['joint_vel'],gravity=o['imu']['gravity'],gyro=o['imu']['gyro'])
 print('step',o['step'],'done',o['done'],o['reason'],'resets',o['resets_left'],'imu',np.round(o['imu']['gravity'],3),np.round(o['imu']['gyro'],3))
 print('body',np.round(np.array(o['proprio']['joint_pos'])[[*range(16),*range(40,45)]],3))
 json.dump({k:v for k,v in o.items() if k not in ('images','depth','proprio')},open('/app/output/status.json','w'))
def move(q,n=25):
 r=Robot(); old=readq(); seq=np.linspace(old,q,n); o=r.step('qpos',action(seq),images=True); np.save('/app/output/target.npy',q); save(o); return o
if __name__=='__main__':
 import sys
 r=Robot()
 if sys.argv[1]=='init':
  q=np.zeros(61); q[[2,7]]=-.4; q[[3,8]]=.8; q[[4,9]]=-.4; np.save('/app/output/target.npy',q); save(r.step('qpos',np.tile(action(q),(50,1))))
 elif sys.argv[1]=='move':
  q=readq()
  for x in sys.argv[3:]:
   k,v=x.split('='); q[names.index(k)]=float(v)
  move(q,int(sys.argv[2]))
 elif sys.argv[1]=='hold': save(r.step('qpos',np.tile(action(readq()),(int(sys.argv[2]),1))))
 elif sys.argv[1]=='see': save(r.observe())
 elif sys.argv[1]=='reset': save(r.reset()); q=np.zeros(61); q[[2,7]]=-.4; q[[3,8]]=.8; q[[4,9]]=-.4; np.save('/app/output/target.npy',q)
PY
